import * as React from "react"
import { parseDate, type CalendarDate } from "@internationalized/date"
import { useFilterActions } from "@querycn/filter-react"
import { CalendarIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/aria/ui/button"
import { Calendar, RangeCalendar } from "@/registry/aria/ui/calendar"
import { Popover, PopoverTrigger } from "@/registry/aria/ui/popover"
import type { FilterValueSlotProps } from "@/registry/aria/filter/filter-rule-row"
import { useDateOnlyFormat } from "@/registry/shared/filter/filter-date-format"

// CalendarDate is a plain day, so `YYYY-MM-DD` maps to it without any time zone.
function toCalendarDate(value: string | undefined): CalendarDate | null {
  if (!value) return null
  try {
    return parseDate(value)
  } catch {
    return null
  }
}

export function DateValueInput({
  id,
  rule,
  field,
  arity,
  setValue,
}: FilterValueSlotProps) {
  const { messages } = useFilterActions()
  const [open, setOpen] = React.useState(false)
  const formatDateOnly = useDateOnlyFormat()
  const range = arity === "range"
  const [from, to] = (
    Array.isArray(rule.value) ? rule.value : [rule.value]
  ).map((value) =>
    typeof value === "string" && value !== "" ? value : undefined
  )
  const label = range
    ? from || to
      ? `${from ? formatDateOnly(from) : "…"} ${messages.rangeSeparator} ${to ? formatDateOnly(to) : "…"}`
      : undefined
    : from && formatDateOnly(from)
  const start = toCalendarDate(from)
  const end = toCalendarDate(to)

  return (
    <PopoverTrigger isOpen={open} onOpenChange={setOpen}>
      <Button
        id={id}
        variant="outline"
        size="sm"
        className={cn(
          "justify-start text-sm font-normal",
          range ? "w-56" : "w-40"
        )}
      >
        <CalendarIcon className="text-muted-foreground" />
        <span className="sr-only">{field.label}: </span>
        <span className={cn("truncate", !label && "text-muted-foreground")}>
          {label || messages.placeholders.date}
        </span>
      </Button>
      <Popover className="w-auto p-0" placement="bottom start">
        {range ? (
          <RangeCalendar
            aria-label={field.label}
            value={start && end ? { start, end } : null}
            onChange={(next) => {
              if (next) setValue([next.start.toString(), next.end.toString()])
            }}
          />
        ) : (
          <Calendar
            aria-label={field.label}
            value={start}
            onChange={(next) => {
              setValue(next.toString())
              setOpen(false)
            }}
          />
        )}
      </Popover>
    </PopoverTrigger>
  )
}

import { useSyncExternalStore } from "react"
import { parseDateOnly, toDateOnly } from "@querycn/filter-core"

const subscribe = () => () => {}

/**
 * `false` on the server and while hydrating, then `true`. Output that depends
 * on the browser (locale, time zone) waits for it, so server and client HTML match.
 */
export function useHydrated(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => true,
    () => false
  )
}

/** A `YYYY-MM-DD` day in the user's locale, e.g. "Sep 25, 2026"; anything else as is. */
export function formatDateOnly(value: string): string {
  const date = parseDateOnly(value)
  return date
    ? date.toLocaleDateString(undefined, { dateStyle: "medium" })
    : value
}

const asIs = (value: string) => value

/** `formatDateOnly` once hydrated; the raw day before. */
export function useDateOnlyFormat(): (value: string) => string {
  return useHydrated() ? formatDateOnly : asIs
}

const ZONED = /T.*(?:Z|[+-]\d{2}:?\d{2})$/i
const pad = (part: number) => String(part).padStart(2, "0")

/**
 * A zoned date-time (e.g. from `toISOString`) as the local `YYYY-MM-DDTHH:mm`
 * a `datetime-local` input can show; other values as is.
 */
export function toDateTimeLocal(value: string): string {
  const date = ZONED.test(value) ? new Date(value) : null
  if (!date || Number.isNaN(date.getTime())) return value
  return `${toDateOnly(date)}T${pad(date.getHours())}:${pad(date.getMinutes())}`
}

import {
  getOperatorArity,
  getOperatorLabel,
  type FieldDefinition,
  type FilterRule,
} from "@querycn/filter-core"
import { useAppliedFilter, useFieldOptions } from "@querycn/filter-react"

import {
  toDateTimeLocal,
  useDateOnlyFormat,
  useHydrated,
} from "@/registry/shared/filter/filter-date-format"

export interface RuleSummary {
  field: string
  operator: string
  /** `undefined` for operators without a value, e.g. "is empty". */
  value: string | undefined
}

/** An applied rule in words, e.g. "Status", "is any of", "Active, Archived". */
export function useRuleSummary(
  rule: FilterRule,
  field: FieldDefinition
): RuleSummary {
  const { context, messages } = useAppliedFilter()
  const hydrated = useHydrated()
  const formatDateOnly = useDateOnlyFormat()
  const items = (
    rule.value === null
      ? []
      : Array.isArray(rule.value)
        ? rule.value
        : [rule.value]
  ).map((item) => (typeof item === "boolean" ? item : String(item)))
  const { getLabel } = useFieldOptions(field, {
    selected: items.filter((item) => typeof item === "string"),
    enabled: false,
  })

  const text = (item: string | boolean) =>
    typeof item === "boolean"
      ? messages.boolean[item ? "true" : "false"]
      : field.type === "date"
        ? formatDateOnly(item)
        : field.type === "datetime"
          ? hydrated
            ? toDateTimeLocal(item).replace("T", " ")
            : item
          : getLabel(item)
  const arity =
    rule.operator === null
      ? undefined
      : getOperatorArity(rule.operator, context.registry.operators)

  return {
    field: field.label,
    operator:
      rule.operator === null
        ? ""
        : getOperatorLabel(messages, rule.operator, field.type),
    value:
      arity === "none" || items.length === 0
        ? undefined
        : items
            .map(text)
            .join(arity === "range" ? ` ${messages.rangeSeparator} ` : ", "),
  }
}
